function quietHours(busy) {
  const points = [...new Set(busy.flat())].sort((a, b) => a - b);
  const gaps = [];
  for (let i = 0; i + 1 < points.length; i++) {
    const x = points[i];
    if (busy.some(([s, e]) => s <= x && x < e)) continue;
    const last = gaps[gaps.length - 1];
    if (last && last[1] === x) last[1] = points[i + 1];
    else gaps.push([x, points[i + 1]]);
  }
  return gaps;
}

