function quietHours(busy) {
  const sorted = busy.map(([s, e]) => [s, e]).sort((a, b) => a[0] - b[0]);
  const gaps = [];
  let end = sorted[0][1];
  for (const [s, e] of sorted) {
    if (s > end) gaps.push([end, s]);
    end = Math.max(end, e);
  }
  return gaps;
}
